// icon_codepoint returns the Lucide glyph codepoint for `name`, and whether
// the name was found.
pub fn icon_codepoint(name string) (u32, bool) {
	if name !in icon_names {
		return u32(0), false
	}
	return icon_names[name], true
}

// icon_exists reports whether `name` is a known Lucide icon name.
pub fn icon_exists(name string) bool {
	return name in icon_names
}
